create extension if not exists pgcrypto;
create type vehicle_status as enum ('draft','active','reserved','sold','archived');
create type job_status as enum ('queued','processing','completed','failed');
create type conversation_state as enum ('AI_ACTIVE','HUMAN_REQUIRED','HUMAN_ACTIVE','RESOLVED');
create type lead_classification as enum ('HOT','WARM','COLD');
create table dealerships(id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, settings jsonb not null default '{}', created_at timestamptz not null default now());
create table dealership_members(dealership_id uuid references dealerships on delete cascade, user_id uuid references auth.users on delete cascade, role text not null check(role in('owner','admin','sales')), primary key(dealership_id,user_id));
create table vehicles(id uuid primary key default gen_random_uuid(), dealership_id uuid not null references dealerships on delete cascade, status vehicle_status not null default 'draft', brand text not null, model text not null, trim text not null default '', model_year int not null check(model_year between 1900 and 2100), mileage int not null check(mileage>=0), asking_price numeric(14,2) not null check(asking_price>=0), minimum_price numeric(14,2), transmission text not null, fuel text not null, color text, condition text, damage_info text, exchange_available boolean not null default false, financing_info text, notes text, published_at timestamptz, sold_at timestamptz, created_at timestamptz not null default now());
create table vehicle_media(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,vehicle_id uuid not null references vehicles on delete cascade,object_path text not null,media_type text not null check(media_type in('image','video')),is_cover boolean not null default false,created_at timestamptz not null default now());
create table generated_contents(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,vehicle_id uuid not null references vehicles on delete cascade,content jsonb not null,provider text not null,created_at timestamptz not null default now());
create table video_jobs(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,vehicle_id uuid not null references vehicles on delete cascade,status job_status not null default 'queued',output_path text,error_code text,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table leads(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,name text,phone text,opted_out_at timestamptz,consent jsonb not null default '{}',created_at timestamptz not null default now());
create table lead_vehicle_interests(lead_id uuid references leads on delete cascade,vehicle_id uuid references vehicles on delete cascade,dealership_id uuid not null references dealerships on delete cascade,preferences jsonb not null default '{}',primary key(lead_id,vehicle_id));
create table conversations(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,lead_id uuid not null references leads on delete cascade,state conversation_state not null default 'AI_ACTIVE',channel text not null,external_id text,unique(dealership_id,channel,external_id));
create table messages(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,conversation_id uuid not null references conversations on delete cascade,external_id text not null,direction text not null check(direction in('inbound','outbound')),body text not null,created_at timestamptz not null default now(),unique(dealership_id,external_id));
create table lead_scores(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,lead_id uuid not null references leads on delete cascade,score int not null check(score between 0 and 100),classification lead_classification not null,signals jsonb not null,reason text not null,created_at timestamptz not null default now());
create table appointments(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,lead_id uuid references leads on delete set null,scheduled_at timestamptz not null,status text not null);
create table sales(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,lead_id uuid references leads on delete set null,vehicle_id uuid references vehicles on delete set null,amount numeric(14,2),sold_at timestamptz not null default now());
create table campaigns(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,name text not null,created_at timestamptz not null default now());
create table content_publications(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,content_id uuid references generated_contents on delete set null,campaign_id uuid references campaigns on delete set null,platform text not null,external_id text,metadata jsonb not null default '{}');
create table lead_attributions(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,lead_id uuid not null references leads on delete cascade,publication_id uuid references content_publications on delete set null,source text not null,utm jsonb not null default '{}');
create table follow_up_rules(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,delay_minutes int not null check(delay_minutes>0),enabled boolean not null default true,template text not null);
create table follow_up_jobs(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references dealerships on delete cascade,lead_id uuid not null references leads on delete cascade,rule_id uuid references follow_up_rules on delete cascade,status job_status not null default 'queued',scheduled_at timestamptz not null,cancel_reason text);
create table audit_logs(id bigint generated always as identity primary key,dealership_id uuid references dealerships on delete set null,actor_id uuid references auth.users on delete set null,action text not null,resource_type text not null,resource_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index vehicles_tenant_status_idx on vehicles(dealership_id,status); create index leads_tenant_created_idx on leads(dealership_id,created_at desc); create index messages_conversation_created_idx on messages(conversation_id,created_at); create index followups_due_idx on follow_up_jobs(status,scheduled_at);
create function is_dealership_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from dealership_members where dealership_id=target and user_id=auth.uid())$$;
do $$ declare t text; begin foreach t in array array['dealership_members','vehicles','vehicle_media','generated_contents','video_jobs','leads','lead_vehicle_interests','conversations','messages','lead_scores','appointments','sales','campaigns','content_publications','lead_attributions','follow_up_rules','follow_up_jobs','audit_logs'] loop execute format('alter table %I enable row level security',t); execute format('create policy tenant_isolation on %I for all using (is_dealership_member(dealership_id)) with check (is_dealership_member(dealership_id))',t); end loop; end $$;
alter table dealerships enable row level security;
create policy dealership_read_update on dealerships for select using (is_dealership_member(id));
create policy dealership_insert on dealerships for insert with check (auth.uid() is not null);
create policy dealership_update on dealerships for update using (is_dealership_member(id)) with check (is_dealership_member(id));
create or replace function create_dealership(dealership_name text, dealership_slug text) returns uuid language plpgsql security definer set search_path=public as $$
declare new_id uuid;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  insert into dealerships(name,slug) values(dealership_name,dealership_slug) returning id into new_id;
  insert into dealership_members(dealership_id,user_id,role) values(new_id,auth.uid(),'owner');
  return new_id;
end $$;
revoke all on function create_dealership(text,text) from public;
grant execute on function create_dealership(text,text) to authenticated;
